kf.blobDrift:
@keyframes blobDrift { 
  0%, 100% { transform: translate(0px) scale(1); }
  33% { transform: translate(40px, -30px) scale(1.06); }
  66% { transform: translate(-25px, 25px) scale(0.94); }
}

kf.leafSway:
@keyframes leafSway { 
  0%, 100% { transform: rotate(0deg) translateY(0px); }
  25% { transform: rotate(2deg) translateY(-5px); }
  50% { transform: rotate(0deg) translateY(-3px); }
  75% { transform: rotate(-1.5deg) translateY(-6px); }
}

kf.lsr-flow:
@keyframes lsr-flow { 
  0% { stroke-dashoffset: 76; opacity: 0.3; }
  50% { opacity: 0.8; }
  100% { stroke-dashoffset: 0; opacity: 0.3; }
}

kf.lsr-ripple:
@keyframes lsr-ripple { 
  0% { opacity: 0.2; transform: scale(0.85); }
  50% { opacity: 0.1; }
  100% { opacity: 0; transform: scale(1.15); }
}
